using StackExchange.Redis;

public class SessionService
{
    private readonly IDatabase _db;

    public SessionService(IConnectionMultiplexer redis)
    {
        _db = redis.GetDatabase();
    }

    public async Task SetSessionAsync(string sessionId, UserSession session, TimeSpan ttl)
    {
        var json = JsonSerializer.Serialize(session);
        await _db.StringSetAsync($"session:{sessionId}", json, ttl);
    }

    public async Task<UserSession?> GetSessionAsync(string sessionId)
    {
        var json = await _db.StringGetAsync($"session:{sessionId}");
        return json.IsNullOrEmpty ? null : JsonSerializer.Deserialize<UserSession>(json);
    }

    public async Task RemoveSessionAsync(string sessionId)
    {
        await _db.KeyDeleteAsync($"session:{sessionId}");
    }
}

public class UserSession
{
    public string UserId { get; set; } = string.Empty;
    public string[] Roles { get; set; } = Array.Empty<string>();
    public DateTimeOffset CreatedAt { get; set; }
}

const Redis = require('ioredis');
const redis = new Redis();

async function setSession(sessionId, session, ttlSeconds) {
  const key = `session:${sessionId}`;
  await redis.set(key, JSON.stringify(session), 'EX', ttlSeconds);
}

async function getSession(sessionId) {
  const key = `session:${sessionId}`;
  const data = await redis.get(key);
  return data ? JSON.parse(data) : null;
}

async function removeSession(sessionId) {
  await redis.del(`session:${sessionId}`);
}

// Example usage
(async () => {
  await setSession('abc123', { userId: 1, roles: ['admin'] }, 1800);
  const session = await getSession('abc123');
  console.log(session);
  await removeSession('abc123');
})();
